"""Tables of the paper, read from the numbers sheet docs/numbers_artigo1.md (no number comes from any other source).
Paper tables: table_criteria.tex (Table 1: runs meeting criteria (i)-(v)), table1_necessity_slim.tex (Table 2: necessity test per
benchmark and group) and table2_occluder_negatives.tex (Table 3: occluder test on images without the target). Supplementary:
table1_necessity.tex (all quantities per group) and table3_zeroshot.tex (zero-shot models). The sheet labels are the internal
names of the research code (see the README glossary); the LaTeX output uses the paper's vocabulary."""
import json, os, re, sys, time
sys.path.insert(0, os.path.dirname(os.path.relpath(__file__))); from common import *
FOLHA = f"{OUT}/docs/numbers_artigo1.md"; txt = open(FOLHA).read(); os.makedirs(f"{OUT}/tables", exist_ok=True)
VAL = dict(re.findall(r"^- \*\*(.+?)\*\* — `(.*)`  $", txt, re.M))
def v(lbl):
    if lbl not in VAL: raise KeyError(lbl)
    return VAL[lbl]
HDR = f"% generated by {os.path.relpath(__file__)} from {os.path.relpath(FOLHA)} (sha256 {sha(FOLHA)[:12]})"
GRP = [("Qwen2-VL-2B, encoder congelado", "Qwen2-VL-2B", "frozen"), ("Qwen2-VL-2B, encoder afinado", "Qwen2-VL-2B", "fine-tuned")] + ([("Qwen2.5-VL-7B, encoder congelado", "Qwen2.5-VL-7B", "frozen"), ("Qwen2.5-VL-7B, encoder afinado", "Qwen2.5-VL-7B", "fine-tuned")] if "QWEN25VL" in FAM_EXTRA else []) + [("SmolVLM2-2.2B, encoder congelado", "SmolVLM2-2.2B", "frozen"),
       ("SmolVLM2-2.2B, encoder afinado", "SmolVLM2-2.2B", "fine-tuned"), ("M3AE, encoder ajuste completo", "M3AE", "full fine-tuning")]
def split(s): return [x.strip() for x in re.split(r" / |; ", s)]
SIGNED = re.compile(r"(?<![\w$.])([+-])(\d+(?:\.\d+)?)(?![\w.])")
def mth(x): return SIGNED.sub(r"$\1\2$", x)
NS = "n.s."
# ---- Table 1: criteria (i)-(v) in two column blocks (fine-tuned runs; zero-shot models), read from the sheet section S24.
ROWS1 = [("Kvasir-VQA-x1", "polipo", "polyp"), ("Kvasir-VQA-x1", "instrumento", "instrument"), ("Kvasir-VQA-x1", "controle negativo (3 templates)", "negative control"),
         ("HEAL-MedVQA", "fechada-sim", "yes-questions"), ("HEAL-MedVQA", "fechada-nao", "no-questions"), ("Medical-Diff-VQA", "fechada-sim", "yes-questions"), ("Medical-Diff-VQA", "fechada-nao", "no-questions")]
_NFT = {k.split(", afinados: (i)")[0]: int(re.search(r"\(de (\d+) linhas", k).group(1)) for k in VAL if k.startswith("Tabela 1, ") and ", afinados: (i) /" in k}
_nft = sorted(set(_NFT.values())); assert len(_nft) == 1, _nft; _nft = _nft[0]
_nzs = sorted(set(int(re.search(r"zero-shot \((\d+) modelos", k).group(1)) for k in VAL if k.startswith("Tabela 1, ") and ", zero-shot (" in k and "): (i) /" in k and "Kvasir" not in k)); assert _nzs == [4], _nzs
CAP1 = r"Runs meeting criteria (i)--(v) of Sec.~\ref{sec:method}, out of " + str(_nft) + r" fine-tuned runs and 4 zero-shot models per row (3 on Kvasir-VQA-x1$^{\ddagger}$); (ii) replaces (i), (iii)--(v) are cumulative, (v) is the necessity test. n.s.: image gain not significant in any model. $^{\ddagger}$LLaVA-Med excluded: answers outside the short-answer format."
L = [HDR, "\\begin{table}[t]", "\\centering", "\\scriptsize", "\\setlength{\\tabcolsep}{3pt}", "\\caption{" + CAP1 + "}", "\\label{tab:criteria}", "\\resizebox{\\columnwidth}{!}{%", "\\begin{tabular}{llrrrrrrrrrr}", "\\toprule",
     "\\multicolumn{2}{l}{} & \\multicolumn{5}{c}{Fine-tuned (of " + str(_nft) + ")} & \\multicolumn{5}{c}{Zero-shot (of 4)} \\\\", "\\cmidrule(lr){3-7}\\cmidrule(lr){8-12}",
     "Benchmark & Question subset & (i) & (ii) & (iii) & (iv) & (v) & (i) & (ii) & (iii) & (iv) & (v) \\\\", "\\midrule"]
for bn, cp, ce in ROWS1:
    ft = v(f"Tabela 1, {bn}, {cp}, afinados: (i) / (ii) / (iii) / (iv) / (v) (de {_nft} linhas; G pareado)").split(" / "); gan = int(v(f"Tabela 1, {bn}, {cp}, afinados: (v) com IUT e Holm dentro da linha / linhas com ganho significativo (de {_nft})").split(" / ")[1])
    zk = [k for k in VAL if k.startswith(f"Tabela 1, {bn}, {cp}, zero-shot (") and "): (i) /" in k]; assert len(zk) == 1, zk; zv, zg = VAL[zk[0]].split("; "); zs_ = zv.split(" / ")
    if gan == 0: ft = ft[:3] + [NS, NS]
    if int(zg) == 0: zs_ = zs_[:3] + [NS, NS]
    if bn == "Kvasir-VQA-x1": zs_[0] = zs_[0] + "$^{\\ddagger}$"
    L.append(f"{bn} & {ce} & " + " & ".join(ft) + " & " + " & ".join(zs_) + " \\\\")
L += ["\\bottomrule", "\\end{tabular}}", "", "\\end{table}"]
open(f"{OUT}/tables/table_criteria.tex", "w").write("\n".join(L) + "\n")
# ---- Table 2: necessity test per benchmark and group. Image gain and Pass (test / sig. gain / runs) from the sheet section S23 (paired image gain:
# the no-image baseline is an adapter of the run's type; no-image M3AE). A1_TABELA2_SEM_HEAL_SIM=1 (default) leaves the HEAL-MedVQA yes-questions
# block out of the paper table (it stays in the supplementary table below).
def GAIN(base, cpt, g): return [x.strip() for x in v(f"{base}, {cpt}, {g}: ganho de imagem, media (DP) (pp); Declared (nec. / sig. gain / runs), M3AE sem imagem").split("; ")]
SEM_HEAL_SIM = os.environ.get("A1_TABELA2_SEM_HEAL_SIM", "1") == "1"
B2 = [("Kvasir-VQA-x1", "polipo", "polyp"), ("Kvasir-VQA-x1", "instrumento", "instrument"), ("HEAL-MedVQA", "fechada-sim", "yes-questions"), ("Medical-Diff-VQA", "fechada-sim", "yes-questions")]
B2 = [x for x in B2 if not (SEM_HEAL_SIM and x[0] == "HEAL-MedVQA" and x[1] == "fechada-sim")]
CAP2 = r"Necessity test per benchmark and group (family $\times$ vision-encoder setting): mean (SD) over three seeds $\times$ two adapters (M3AE: three seeds, full fine-tuning). All quantities in pp: image gain $\Gimg$, control-occlusion drop $C$ and $\Dnec$ (Sec.~\ref{sec:method}). Pass: runs passing the test (criterion (v)) / runs with a significant gain / runs. Per-run estimates and CIs are released with the code."
L = [HDR, "\\begin{table*}[t]", "\\centering", "\\scriptsize", "\\setlength{\\tabcolsep}{1pt}", "\\caption{" + CAP2 + "}", "\\label{tab:necessity_slim}", "{%", "\\begin{tabular}{llllrrrrl}", "\\toprule",
     "Benchmark & Question subset & Model & Vision encoder & Image gain & Control-occlusion drop, black & $\\Dnec$ black & $\\Dnec$ blur & Pass (test / sig. gain / runs) \\\\", "\\midrule"]
for base, cpt, cen in B2:
    for i, (g, fam, enc) in enumerate(GRP):
        gain, dec = GAIN(base, cpt, g)
        d = split(v(f"{base}, {cpt}, {g}: Delta preto / blur 10 % / cor media (pp)")); c = split(v(f"{base}, {cpt}, {g}: custo da mascara deslocada, preto (pp) / suficiencia, preto / criterio B"))
        L.append(" & ".join([base if i == 0 else "", cen if i == 0 else "", fam, enc, mth(gain), mth(c[0]), mth(d[0]), mth(d[1]), dec]) + " \\\\")
    L.append("\\midrule" if (base, cpt) != B2[-1][:2] else "\\bottomrule")
L += ["\\end{tabular}}", "", "\\end{table*}"]
open(f"{OUT}/tables/table1_necessity_slim.tex", "w").write("\n".join(L).replace("—", "--") + "\n")
# ---- Table 3: occluder test on images without the target
C2 = [("Kvasir-VQA-x1", "SHAM_ART", "Box artefact$^{\\dagger}$"), ("Kvasir-VQA-x1", "SHAM_POL_Q3", "Polyp (Q3 size)"), ("Kvasir-VQA-x1", "SHAM_INS", "Instrument"), ("HEAL-MedVQA", "alvo", "HEAL-MedVQA"), ("Medical-Diff-VQA", "oclusor", "Medical-Diff-VQA")]
def rate(base, key, fill, g):
    return v(f"{base}, {key}_{'black' if base == 'Kvasir-VQA-x1' and fill == 'preto' else ('blur10' if base == 'Kvasir-VQA-x1' else fill)}, {g}: taxa induzida (pp) media (DP); linhas com IC > 0 / IC < 0").split(";")[0]
CAP3 = r"Occluder-induced affirmative rate $\Delta$Yes (pp) on images without the target: group means (SD), black / blur fill. Kvasir-VQA-x1: box-artefact question$^{\dagger}$ (532 questions), polyp-shaped patch of third-quartile polyp area (Q3; 1\,199 questions) and instrument-shaped patch (1\,411 questions). Chest X-rays: HEAL-MedVQA's 735 no-questions (occluder on the queried region) and Medical-Diff-VQA's 391 no-questions (occluder on the regions where the finding is most frequent)."
L = [HDR, "\\begin{table*}[t]", "\\centering", "\\scriptsize", "\\setlength{\\tabcolsep}{2pt}", "\\caption{" + CAP3 + "}", "\\label{tab:occluder}", "{%", "\\begin{tabular}{ll" + "rr" * len(C2) + "}", "\\toprule",
     "Model & Vision encoder & " + " & ".join(f"\\multicolumn{{2}}{{c}}{{{t}}}" for _, _, t in C2) + " \\\\", " & & " + " & ".join("black & blur" for _ in C2) + " \\\\", "\\midrule"]
for g, fam, enc in GRP: L.append(f"{fam} & {enc} & " + " & ".join(f"{mth(rate(b, k, 'preto', g))} & {mth(rate(b, k, 'blur10', g))}" for b, k, _ in C2) + " \\\\")
L += ["\\bottomrule", "\\end{tabular}}", "", "\\end{table*}"]
open(f"{OUT}/tables/table2_occluder_negatives.tex", "w").write("\n".join(L).replace("—", "--") + "\n")
# ---- supplementary: full necessity table (all quantities, no-image arm accuracy, region-mean fill, sufficiency; all benchmarks and groups) and zero-shot table
B = [("Kvasir-VQA-x1", "polipo", "polyp"), ("Kvasir-VQA-x1", "instrumento", "instrument"), ("HEAL-MedVQA", "fechada-sim", "closed-ended, answer yes"), ("Medical-Diff-VQA", "fechada-sim", "closed-ended, answer yes")]
cols = ["Benchmark", "Class", "Model", "Vision encoder", "Intact", "No-image baseline", "Image gain", "Control-occlusion drop", "$\\Delta$ black", "$\\Delta$ blur", "$\\Delta$ region-mean", "Sufficiency", "Pass (test / sig. gain / runs)"]
L = [HDR, "\\begin{table*}[t]", "\\centering", "\\scriptsize", "\\setlength{\\tabcolsep}{3pt}",
     "\\caption{Supplementary: necessity test per benchmark, model family and vision-encoder group: mean (SD) over three seeds and the two adapters (LoRA, DoRA; M3AE: full fine-tuning). Accuracies in \\%; differences in percentage points. No-image baseline = accuracy of the shared LoRA no-image baseline of the family and seed (sheet sections S3--S5); Image gain = intact-image accuracy minus the accuracy of the paired no-image baseline (an adapter of the run's type; M3AE: no image; sheet section S23). Control-occlusion drop = intact-image accuracy minus accuracy under the matched control occlusion. $\\Delta$ (necessity effect) = accuracy under the matched control occlusion minus accuracy with the target occluded. Sufficiency: accuracy with everything outside the target occluded, divided by the intact accuracy. Pass: runs passing the test (criterion (v)) / runs with a significant gain / runs.}",
     "\\label{tab:necessity}", "\\begin{tabular}{llll" + "r" * (len(cols) - 5) + "l}", "\\toprule", " & ".join(cols) + " \\\\", "\\midrule"]
for base, cpt, cen in B:
    for i, (g, fam, enc) in enumerate(GRP):
        a = split(v(f"{base}, {cpt}, {g}: Acc intacta / text-decoder-only / TF-IDF (%)")); gain, dec = GAIN(base, cpt, g)
        d = split(v(f"{base}, {cpt}, {g}: Delta preto / blur 10 % / cor media (pp)")); c = split(v(f"{base}, {cpt}, {g}: custo da mascara deslocada, preto (pp) / suficiencia, preto / criterio B"))
        L.append(" & ".join([base if i == 0 else "", cen if i == 0 else "", fam, enc, a[0], a[1], gain, c[0], d[0], d[1], d[2], c[1], dec]) + " \\\\")
    L.append("\\midrule" if (base, cpt) != B[-1][:2] else "\\bottomrule")
L += ["\\end{tabular}", "\\end{table*}"]
open(f"{OUT}/tables/table1_necessity.tex", "w").write("\n".join(L).replace("—", "--") + "\n")
ZS4 = [("MEDGEMMA", "MedGemma 1.5 4B"), ("QWEN25VL", "Qwen2.5-VL 7B"), ("LLAVA_MED", "LLaVA-Med v1.5 7B"), ("MEDVLTHINKER", "MedVLThinker 7B")]
ZB = [("KVASIR", "Kvasir-VQA-x1", "polipo", False), ("HEAL", "HEAL-MedVQA", "fechada-sim", True), ("MIMIC", "Medical-Diff-VQA", "fechada-sim", True)]
L = [HDR, "\\begin{table*}[t]", "\\centering", "\\scriptsize", "\\setlength{\\tabcolsep}{2.5pt}",
     "\\caption{Zero-shot models under the same test (Kvasir-VQA-x1: polyp class; X-ray benchmarks: closed-ended questions answered yes). Image gain = accuracy with the image minus accuracy without the image of the same model, in percentage points (95\\% image-bootstrap CI); $\\Delta$ (necessity effect) under black fill and Gaussian blur with 95\\% CI. Dual-fill: yes/no when the image gain is resolvable (CI lower bound above zero), otherwise n.r. (not resolvable: $\\Delta$ not read). Affirmative rate: share of yes answers over all closed-ended questions (answer yes and no), with the intact image and without the image. $^{\\ddagger}$Answers outside the short-answer format (accuracy 0 on the intact image).}",   # caption of the supplementary zero-shot table as in the submitted paper (v32d)
     "\\label{tab:zeroshot}", "\\begin{tabular}{l" + "".join("rrrl" + ("rr" if x else "") for *_, x in ZB) + "}", "\\toprule",
     "Model & " + " & ".join(f"\\multicolumn{{{6 if x else 4}}}{{c}}{{{t}}}" for _, t, _, x in ZB) + " \\\\",
     " & " + " & ".join("Image gain & $\\Delta$ black & $\\Delta$ blur & Dual-fill" + (" & Aff.\\ intact & Aff.\\ no image" if x else "") for *_, x in ZB) + " \\\\", "\\midrule"]
for m, mn in ZS4:
    cells = []
    for b, bn, c, aff in ZB:
        if m == "LLAVA_MED" and b == "KVASIR": cells.append("--$^{\\ddagger}$ & -- & -- & --"); continue
        hh = v(f"zero-shot {m}_ZEROSHOT_{b}, {c}: Acc intacta / sem imagem (%); headroom [IC] (pp)").split(";")[1].strip()
        lo = float(re.search(r"\[([+\-]?\d+\.\d+),", hh).group(1))
        dd = v(f"zero-shot {m}_ZEROSHOT_{b}, {c}: Delta preto [IC] / blur 10 % [IC] (pp); criterio B; suficiencia").split(";")
        dp, db = [x.strip() for x in dd[0].split(" / ")]; cb = ({"sim": "yes", "nao": "no"}[dd[1].strip()]) if lo > 0 else "n.r."
        cell = f"{hh} & {dp} & {db} & {cb}"
        if aff:
            ai = v(f"{bn}, zero-shot {m}, intacta: sensibilidade / especificidade / taxa afirmativa (%) [IC]").split(" / ")[2].split(" [")[0]
            an = v(f"{bn}, zero-shot {m}, text_only_ou_sem_imagem: sensibilidade / especificidade / taxa afirmativa (%) [IC]").split(" / ")[2].split(" [")[0]
            cell += f" & {ai} & {an}"
        cells.append(cell)
    L.append(f"{mn}{'$^{\\ddagger}$' if m == 'LLAVA_MED' else ''} & " + " & ".join(cells) + " \\\\")
L += ["\\bottomrule", "\\end{tabular}", "\\end{table*}"]
open(f"{OUT}/tables/table3_zeroshot.tex", "w").write("\n".join(L).replace("—", "--") + "\n")
USED = ["table_criteria.tex", "table1_necessity_slim.tex", "table2_occluder_negatives.tex"]
BAD = re.compile(r"placebo|sham|\bTXT\b|\bC0\b|\bC1\b|\bM0\b|\bE[0-9]+\b|torre|tower|\bVT\b|\bFT\b|\bv[5-7]\b|RADORIG|piso|\barms?\b|headroom|text-decoder|displaced|resolvab|readable|ladder|\bL[0-3]\b|dual[- ]fill|matched-control cost|answer-yes|answer-no|n\.r\.", re.I)
hits = {f: [l for l in open(f"{OUT}/tables/{f}").read().splitlines() if not l.startswith("%") and BAD.search(l)] for f in os.listdir(f"{OUT}/tables") if f.endswith(".tex")}
json.dump({"t": time.strftime("%Y-%m-%d %H:%M:%S"), "sheet_sha256": sha(FOLHA), "script_sha256": sha(os.path.relpath(__file__)), "paper_tables": USED, "files": {f: sha(f"{OUT}/tables/{f}") for f in sorted(os.listdir(f"{OUT}/tables")) if f.endswith(".tex")},
           "internal_terms_in_paper_tables": {f: hits.get(f, []) for f in USED}, "internal_terms_in_supplementary": {k: v_ for k, v_ in hits.items() if v_ and k not in USED}}, open(f"{OUT}/tables/manifest.json", "w"), indent=1)
print("tables ok; internal terms in paper tables:", {f: len(hits.get(f, [])) for f in USED})
